function statusOf(error: unknown): number | null {
  if (error instanceof ApiError) return error.status;
  if (error !== null && typeof error === "object" && "status" in error) {
    const status = (error as { status?: unknown }).status;
    return typeof status === "number" ? status : null;
  }
  return null;
}

function messageOf(error: unknown, fallback: string): string {
  return error instanceof Error && error.message ? error.message : fallback;
}

export function useThreadTree(
  sessionId: string | undefined,
  transport: RuntimeTransport | undefined,
): UseThreadTreeState {
  const [loading, setLoading] = useState(Boolean(sessionId && transport));
  const [error, setError] = useState<string | null>(null);
  const [tree, setTree] = useState<ThreadTreeOut | null>(null);
  const [children, setChildren] = useState<ThreadChildrenOut | null>(null);
  const [limits, setLimits] = useState<ThreadLimitsOut | null>(null);
  const [result, setResult] = useState<ThreadResultOut | null>(null);
  const generationRef = useRef(0);
  const mountedRef = useRef(true);
  const pendingActionsRef = useRef(new Set<string>());

  const refresh = useCallback(async (): Promise<void> => {
    if (!sessionId || !transport) {
      if (mountedRef.current) {
        setLoading(false);
        setTree(null);
        setChildren(null);
        setLimits(null);
        setResult(null);
      }
      return;
    }
    const generation = generationRef.current;
    setLoading(true);
    setError(null);
    const base = `/api/threads/${sessionId}`;
    const resultRequest = transport
      .get<ThreadResultOut>(`${base}/result`)
      .catch((requestError: unknown) => {
        if (statusOf(requestError) === 404) return null;
        throw requestError;
      });
    try {
      const [nextTree, nextChildren, nextLimits, nextResult] = await Promise.all([
        transport.get<ThreadTreeOut>(`${base}/tree`),
        transport.get<ThreadChildrenOut>(`${base}/children`),
        transport.get<ThreadLimitsOut>(`${base}/limits`),
        resultRequest,
      ]);
      if (!mountedRef.current || generation !== generationRef.current) return;
      setTree(nextTree);
      setChildren(nextChildren);
      setLimits(nextLimits);
      setResult(nextResult);
      setError(null);
    } catch (requestError) {
      if (!mountedRef.current || generation !== generationRef.current) return;
      setError(messageOf(requestError, "Failed to load thread tree"));
    } finally {
      if (mountedRef.current && generation === generationRef.current) setLoading(false);
    }
  }, [sessionId, transport]);

  useEffect(() => {
    mountedRef.current = true;
    generationRef.current += 1;
    setTree(null);
    setChildren(null);
    setLimits(null);
    setResult(null);
    void refresh();
    return () => {
      mountedRef.current = false;
    };
  }, [refresh]);

  async function runMutation<T>(
    action: string,
    operation: () => Promise<T>,
    fallback: string,
  ): Promise<T | null> {
    if (!transport || !sessionId || pendingActionsRef.current.has(action)) return null;
    pendingActionsRef.current.add(action);
    setError(null);
    try {
      return await operation();
    } catch (requestError) {
      if (mountedRef.current) setError(messageOf(requestError, fallback));
      return null;
    } finally {
      pendingActionsRef.current.delete(action);
    }
  }

  async function createChild(body: ThreadChildCreate): Promise<ThreadSpawnOut | null> {
    const spawn = await runMutation(
      "create",
      () => transport!.post<ThreadSpawnOut>(`/api/threads/${sessionId}/children`, body),
      "Failed to create child thread",
    );
    if (!spawn || !mountedRef.current) return spawn;
    setTree((currentTree) => {
      if (!currentTree) return currentTree;
      return {
        ...currentTree,
        placeholders: [
          ...currentTree.placeholders,
          {
            delegation_id: spawn.delegation_id,
            parent_id: sessionId!,
            title: body.title,
            role: body.role ?? "general",
            status: "provisioning",
            created_at: new Date().toISOString(),
          },
        ],
        thread_count: currentTree.thread_count + 1,
      };
    });
    await refresh();
    return spawn;
  }

  async function cancelChild(threadId: string): Promise<boolean> {
    const response = await runMutation(
      `cancel:${threadId}`,
      () => transport!.post<ThreadSpawnOut>(`/api/threads/${threadId}/cancel`),
      "Failed to cancel child thread",
    );
    if (!response) return false;
    await refresh();
    return true;
  }

  async function retryChild(
    threadId: string,
    body: ThreadRetryCreate,
  ): Promise<ThreadSpawnOut | null> {
    const response = await runMutation(
      `retry:${threadId}`,
      () => transport!.post<ThreadSpawnOut>(`/api/threads/${threadId}/retry`, body),
      "Failed to retry child thread",
    );
    if (!response) return null;
    await refresh();
    return response;
  }

  async function reportResult(
    threadId: string,
    body: ThreadResultReportCreate,
  ): Promise<ThreadResultOut | null> {
    const response = await runMutation(
      `report:${threadId}`,
      () => transport!.post<ThreadResultOut>(`/api/threads/${threadId}/report`, body),
      "Failed to report thread result",
    );
    if (!response) return null;
    await refresh();
    return response;
  }

  return {
    loading,
    error,
    tree,
    children,
    limits,
    result,
    refresh,
    createChild,
    cancelChild,
    retryChild,
    reportResult,
  };
}

import { useState } from "react";
import type { ThreadResultOut, ThreadTreeOut, ThreadLimitsOut, ThreadChildCreate } from "../../api/client";
import ManualChildDialog from "./ManualChildDialog";
import ThreadNode from "./ThreadNode";
import ThreadResult from "./ThreadResult";
export interface ThreadPanelProps { tree: ThreadTreeOut | null; loading?: boolean; error?: string | null; limits?: ThreadLimitsOut | null; result?: ThreadResultOut | null; resultLoading?: boolean; resultError?: string | null; currentThreadId?: string | null; onNavigate?: (threadId: string) => void; onCancel?: (threadId: string) => void; onRetry?: (threadId: string) => void; onCreateChild?: (payload: ThreadChildCreate) => void | Promise<void>; }
export default function ThreadPanel({ tree, loading = false, error = null, limits = null, result = null, resultLoading = false, resultError = null, onCreateChild, currentThreadId = null, onNavigate, onCancel, onRetry }: ThreadPanelProps) {
  const [dialogOpen, setDialogOpen] = useState(false);
  if (loading) return <section role="status">Loading thread tree...</section>;
  if (error) return <section role="alert">{error}</section>;
  if (!tree) return <section>No thread tree available.</section>;
  const currentId = currentThreadId ?? tree.root.id;
  return (
    <section data-testid="thread-panel" className="flex min-h-0 w-full min-w-0 flex-col overflow-hidden">
      <button type="button" onClick={() => setDialogOpen(true)} disabled={!onCreateChild || !tree.root.can_spawn_child}>Create child thread</button>
      <nav aria-label="Thread tree" className="min-h-0 min-w-0 overflow-y-auto overflow-x-hidden">
        <ThreadNode node={tree.root} current={currentId === tree.root.id} onNavigate={onNavigate} onCancel={onCancel} onRetry={onRetry} />
        {tree.nodes.map((node) => <ThreadNode key={node.id} node={node} current={currentId === node.id} onNavigate={onNavigate} onCancel={onCancel} onRetry={onRetry} />)}
        {tree.placeholders.map((placeholder) => <ThreadNode key={placeholder.delegation_id} placeholder={placeholder} current={currentId === placeholder.delegation_id} onNavigate={onNavigate} onCancel={onCancel} onRetry={onRetry} />)}
      </nav>
      {(result !== null || resultLoading || resultError !== null) && (
        <div className="min-h-0 min-w-0 overflow-y-auto border-t border-gray-800 p-3">
          <ThreadResult result={result} loading={resultLoading} error={resultError} />
        </div>
      )}
      <ManualChildDialog open={dialogOpen} onClose={() => setDialogOpen(false)} onSubmit={async (payload) => { await onCreateChild?.(payload); setDialogOpen(false); }} limits={limits} />
    </section>
  );
}

import type {
  ThreadNodeOut,
  ThreadPlaceholderOut,
} from "../../api/client";
import ThreadStatusBadge, { type ThreadStatus } from "./ThreadStatusBadge";

const MAX_INDENT_DEPTH = 6;
const ACTIVE_STATES = new Set<ThreadStatus>(["provisioning", "queued", "running"]);
const RETRYABLE_STATES = new Set<ThreadStatus>(["failed", "cancelled", "interrupted"]);

export interface ThreadNodeProps {
  node?: ThreadNodeOut;
  placeholder?: ThreadPlaceholderOut;
  current?: boolean;
  onNavigate?: (threadId: string) => void;
  onCancel?: (threadId: string) => void;
  onRetry?: (threadId: string) => void;
  className?: string;
}

function roleTitle(role: string): string {
  const readableRole = role.trim() || "general";
  return `${readableRole.charAt(0).toUpperCase()}${readableRole.slice(1)} thread`;
}

function nodeTitle(node: ThreadNodeOut): string {
  return node.title?.trim() || roleTitle(node.role);
}

export default function ThreadNode({
  node,
  placeholder,
  current = false,
  onNavigate,
  onCancel,
  onRetry,
  className = "",
}: ThreadNodeProps) {
  if (!node && !placeholder) return null;
  if (node && placeholder) return null;

  const title = node ? nodeTitle(node) : placeholder!.title;
  const role = node?.role ?? placeholder!.role;
  const state: ThreadStatus = node?.state ?? placeholder!.status;
  const depth = Math.min(Math.max(node?.depth ?? 0, 0), MAX_INDENT_DEPTH);
  const actionId = node?.id ?? placeholder!.delegation_id;
  const retryable = RETRYABLE_STATES.has(state);
  const cancellable = ACTIVE_STATES.has(state);

  return (
    <div
      className={`flex min-w-0 items-center gap-1 border-b border-gray-800/70 py-1 ${current ? "bg-blue-500/10" : ""} ${className}`.trim()}
      style={{ paddingInlineStart: `${depth}rem` }}
    >
      <button
        type="button"
        onClick={() => onNavigate?.(actionId)}
        aria-current={current ? "page" : undefined}
        aria-label={`Open ${title}`}
        className="min-w-0 flex-1 rounded px-2 py-2 text-left text-sm text-gray-200 hover:bg-gray-800 focus:outline-none focus:ring-1 focus:ring-blue-500"
      >
        <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
          <span className="min-w-0 flex-1 truncate font-medium" title={title}>{title}</span>
          <span className="shrink-0 text-xs text-gray-500">{role}</span>
          <ThreadStatusBadge state={state} />
          {current ? <span className="sr-only">Current thread</span> : null}
        </span>
      </button>
      {onCancel && cancellable ? (
        <button type="button" onClick={() => onCancel(actionId)} aria-label={`Cancel ${title}`} className="min-h-touch shrink-0 rounded px-2 text-xs text-gray-400 hover:bg-gray-800 hover:text-gray-200 focus:outline-none focus:ring-1 focus:ring-blue-500">Cancel</button>
      ) : null}
      {onRetry && retryable ? (
        <button type="button" onClick={() => onRetry(actionId)} aria-label={`Retry ${title}`} className="min-h-touch shrink-0 rounded px-2 text-xs text-gray-400 hover:bg-gray-800 hover:text-gray-200 focus:outline-none focus:ring-1 focus:ring-blue-500">Retry</button>
      ) : null}
    </div>
  );
}

