import { randomUUID } from "node:crypto";

export const ORCHESTRATION_REQUEST_TYPE = "orchestration_request";

export function createOrchestrationRpc({
  sessionId,
  capability,
  send,
  timeoutMs = 60_000,
}) {
  /** Pending map: request_id -> resolver entry. */
  const pending = new Map();

  function request(operation, args) {
    const requestId = randomUUID();
    const frame = {
      type: ORCHESTRATION_REQUEST_TYPE,
      id: sessionId,
      request_id: requestId,
      capability,
      operation,
      arguments: args ?? {},
    };
    return new Promise((resolve, reject) => {
      const entry = { resolve, reject, timer: null };
      pending.set(requestId, entry);
      entry.timer = setTimeout(() => {
        const error = new Error("The orchestration request timed out.");
        error.code = "orchestration_timeout";
        pending.delete(requestId);
        reject(error);
      }, timeoutMs);
      // Keep Node from hanging on this timer after tests/process end.
      entry.timer.unref?.();
      try {
        send(frame);
      } catch (err) {
        clearTimeout(entry.timer);
        pending.delete(requestId);
        reject(err);
      }
    });
  }

  /** Route one inbound frame. Returns true when the frame was consumed. */
  function handleFrame(message) {
    if (!message || typeof message !== "object") {
      return false;
    }
    if (message.type !== "orchestration_response") {
      return false;
    }
    const entry = pending.get(message.request_id);
    if (!entry) {
      return true;
    }
    pending.delete(message.request_id);
    if (entry.timer) {
      clearTimeout(entry.timer);
    }
    if (message.ok === true) {
      entry.resolve(message.result ?? {});
    } else {
      const error = new Error(
        message?.error?.message || "The orchestration operation failed.",
      );
      error.code = message?.error?.code || "handler_failed";
      entry.reject(error);
    }
    return true;
  }

  /** Reject every pending request (query teardown or disconnect). */
  function dispose() {
    for (const entry of [...pending.values()]) {
      const error = new Error("The orchestration channel was disconnected.");
      error.code = "orchestration_disconnected";
      entry.reject(error);
    }
    pending.clear();
  }

  return {
    request,
    handleFrame,
    dispose,
    get pendingCount() {
      return pending.size;
    },
  };
}

import { Type } from "typebox";

const pingSchema = Type.Object({
  message: Type.Optional(
    Type.String({
      description: "Optional short message echoed back by the backend.",
      maxLength: 256,
    }),
  ),
});

export function createThreadBridgePingTool({ rpcForCall }) {
  if (typeof rpcForCall !== "function") {
    throw new TypeError("rpcForCall must be a function");
  }
  return {
    name: "thread_bridge_ping",
    label: "Thread bridge ping",
    description:
      "Harmless round-trip check of the Yinshi thread orchestration bridge.",
    parameters: pingSchema,
    async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
      const rpc = rpcForCall();
      if (!rpc) {
        throw new Error(
          "Thread bridge ping failed: the orchestration channel is not active.",
        );
      }
      const result = await rpc.request("ping_thread_bridge", {
        message: typeof params?.message === "string" ? params.message : "",
      });
      return {
        content: [{ type: "text", text: JSON.stringify(result) }],
        details: undefined,
      };
    },
  };
}

